fn collect_declared_type_names(defs: &[TypeDefLine]) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for def in defs {
        if !def.name.is_empty() && def.kind != "fn" {
            names.insert(def.name.clone());
        }
        if let Some(original) = &def.original_name {
            names.insert(original.clone());
        }
        if def.kind == "raw" {
            let tokens = def.def.split_whitespace().collect::<Vec<_>>();
            let name = match tokens.as_slice() {
                ["export", "interface" | "type" | "class", name, ..] => Some(*name),
                ["export", "declare", "class", name, ..] => Some(*name),
                _ => None,
            };
            if let Some(name) = name {
                names.insert(
                    name.trim_end_matches(['<', '{', ';'])
                        .split('<')
                        .next()
                        .unwrap_or(name)
                        .to_string(),
                );
            }
        }
    }
    names
}

fn insert_generated_name(
    name: &str,
    kind: &str,
    raw_names: &BTreeSet<String>,
    generated: &mut BTreeSet<String>,
) -> Result<()> {
    validate_arkts_export_identifier(name)?;
    if raw_names.contains(name) || !generated.insert(name.to_string()) {
        bail!("Harmony generated stream {kind} name collision for `{name}`");
    }
    Ok(())
}

fn harmony_arguments(arguments: &[HarmonyFacadeArgument]) -> String {
    arguments
        .iter()
        .map(|argument| format!("{}: {}", argument.name, argument.r#type.public_type()))
        .collect::<Vec<_>>()
        .join(", ")
}

fn harmony_argument_names(arguments: &[HarmonyFacadeArgument]) -> String {
    arguments
        .iter()
        .map(|argument| argument.name.as_str())
        .collect::<Vec<_>>()
        .join(", ")
}

fn render_harmony_output_implementation(output: &HarmonyOutputStreamContract) -> String {
    let args = harmony_arguments(&output.arguments);
    let item_type = output.item_type.public_type();
    let error_type = output.error_type.public_type();
    let pass = harmony_argument_names(&output.arguments);
    let fields = output
        .arguments
        .iter()
        .enumerate()
        .map(|(index, argument)| {
            format!(
                "  private __arg{index}: {};\n",
                argument.r#type.public_type()
            )
        })
        .collect::<String>();
    let assignments = output
        .arguments
        .iter()
        .enumerate()
        .map(|(index, argument)| format!("    this.__arg{index} = {};\n", argument.name))
        .collect::<String>();
    let call_args = if pass.is_empty() { String::new() } else { pass };
    let this_call_args = output
        .arguments
        .iter()
        .enumerate()
        .map(|(index, _argument)| format!("this.__arg{index}"))
        .collect::<Vec<_>>()
        .join(", ");
    let error_type_name = serde_json::to_string(&error_type)
        .expect("Harmony stream error type name is JSON serializable");
    format!(
        r#"

export class {pull_class} extends __UniFfiPullStream<{item_type}, {error_type}> {{
{fields}  constructor({args}) {{
    super();
{assignments}    this.setHandle(native.{function}({call_args}));
  }}

  protected nextNative(handle: bigint): Promise<UniFfiStreamResult<{item_type}>> {{
    return native.{next_function}(handle).then(
      (result: {next_type}): UniFfiStreamResult<{item_type}> =>
        new UniFfiStreamResult<{item_type}>(result.done, result.value)
    );
  }}

  protected cancelNative(handle: bigint): void {{
    native.{cancel_function}(handle);
  }}

  protected errorTypeName(): string {{
    return {error_type_name};
  }}
}}

export function {stream_factory}({args}): {pull_class} {{
  return new {pull_class}({call_args});
}}

export class {events_class} extends __UniFfiEventsStream<{item_type}, {error_type}> {{
{fields}  constructor({args}) {{
    super();
{assignments}  }}

  protected startNative(): bigint {{
    return native.{function}({this_call_args});
  }}

  protected nextNative(handle: bigint): Promise<UniFfiStreamResult<{item_type}>> {{
    return native.{next_function}(handle).then(
      (result: {next_type}): UniFfiStreamResult<{item_type}> =>
        new UniFfiStreamResult<{item_type}>(result.done, result.value)
    );
  }}

  protected cancelNative(handle: bigint): void {{
    native.{cancel_function}(handle);
  }}

  protected errorTypeName(): string {{
    return {error_type_name};
  }}
}}

export function {events_factory}({args}): {events_class} {{
  return new {events_class}({call_args});
}}
"#,
        pull_class = output.pull_class,
        item_type = item_type,
        error_type = error_type,
        fields = fields,
        args = args,
        assignments = assignments,
        function = output.function,
        call_args = call_args,
        this_call_args = this_call_args,
        next_function = output.next_function,
        next_type = output.next_type,
        cancel_function = output.cancel_function,
        stream_factory = output.stream_factory,
        events_class = output.events_class,
        events_factory = output.events_factory,
        error_type_name = error_type_name,
    )
}

fn render_harmony_input_implementation(input: &HarmonyInputStreamContract) -> String {
    let envelope = format!("__{}InputNextEnvelope", input.suffix);
    let item_type = input.item_type.public_type();
    let error_type = input.error_type.public_type();
    format!(
        r#"

class {envelope} implements {next_type} {{
  ok: boolean;
  done?: boolean;
  value?: {item_type};
  error?: {error_type};

  constructor(ok: boolean) {{
    this.ok = ok;
  }}
}}

export class {source_class}
  extends __UniFfiInputSource<{item_type}, {error_type}, {envelope}>
  implements __UniffiInputStream<{next_type}> {{
  protected valueEnvelope(item: {item_type}): {envelope} {{
    const result: {envelope} = new {envelope}(true);
    result.done = false;
    result.value = item;
    return result;
  }}

  protected doneEnvelope(): {envelope} {{
    const result: {envelope} = new {envelope}(true);
    result.done = true;
    return result;
  }}

  protected errorEnvelope(error: {error_type}): {envelope} {{
    const result: {envelope} = new {envelope}(false);
    result.error = error;
    return result;
  }}
}}

export class {writer_class} {{
  private source: {source_class};

  constructor(source: {source_class}) {{
    this.source = source;
  }}

  write(item: {item_type}): Promise<void> {{
    return this.source.write(item);
  }}

  end(): void {{
    this.source.end();
  }}

  fail(error: UniFfiInputFailure<{error_type}>): void {{
    this.source.fail(error);
  }}
}}

export class {channel_class} {{
  writer: {writer_class};
  source: {source_class};

  constructor() {{
    this.source = new {source_class}();
    this.writer = new {writer_class}(this.source);
  }}
}}

export function {factory}(): {channel_class} {{
  return new {channel_class}();
}}
"#,
        envelope = envelope,
        next_type = input.next_type,
        item_type = item_type,
        error_type = error_type,
        source_class = input.source_class,
        writer_class = input.writer_class,
        channel_class = input.channel_class,
        factory = input.factory,
    )
}

fn render_harmony_output_declarations(output: &HarmonyOutputStreamContract) -> String {
    let args = harmony_arguments(&output.arguments);
    let item_type = output.item_type.public_type();
    let error_type = output.error_type.public_type();
    format!(
        r#"

export declare class {pull_class} implements UniFfiStream<{item_type}> {{
  constructor({args});
  next(): Promise<UniFfiStreamResult<{item_type}>>;
  cancel(): Promise<void>;
}}

export declare function {stream_factory}({args}): {pull_class};

export declare class {events_class} {{
  constructor({args});
  on(type: 'data', callback: Callback<{item_type}>): void;
  on(type: 'error', callback: ErrorCallback<BusinessError<UniFfiStreamErrorData<{error_type}>>>): void;
  on(type: 'done', callback: Callback<void>): void;
  off(type: 'data', callback?: Callback<{item_type}>): void;
  off(type: 'error', callback?: ErrorCallback<BusinessError<UniFfiStreamErrorData<{error_type}>>>): void;
  off(type: 'done', callback?: Callback<void>): void;
  start(): void;
  cancel(): void;
}}

export declare function {events_factory}({args}): {events_class};
"#,
        pull_class = output.pull_class,
        item_type = item_type,
        args = args,
        stream_factory = output.stream_factory,
        events_class = output.events_class,
        error_type = error_type,
        events_factory = output.events_factory,
    )
}

fn render_harmony_input_declarations(input: &HarmonyInputStreamContract) -> String {
    let item_type = input.item_type.public_type();
    let error_type = input.error_type.public_type();
    format!(
        r#"

export declare class {source_class} implements __UniffiInputStream<{next_type}> {{
  readonly handle: number;
  next(error: Error | null, handle: number): Promise<{next_type}>;
  cancel(error: Error | null, handle: number): void;
}}

export declare class {writer_class} {{
  constructor(source: {source_class});
  write(item: {item_type}): Promise<void>;
  end(): void;
  fail(error: UniFfiInputFailure<{error_type}>): void;
}}

export declare class {channel_class} {{
  writer: {writer_class};
  source: {source_class};
  constructor();
}}

export declare function {factory}(): {channel_class};
"#,
        source_class = input.source_class,
        next_type = input.next_type,
        writer_class = input.writer_class,
        item_type = item_type,
        error_type = error_type,
        channel_class = input.channel_class,
        factory = input.factory,
    )
}

fn validate_arkts_export_identifier(name: &str) -> Result<()> {
    let mut chars = name.chars();
    let valid = chars
        .next()
        .is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_' || ch == '$')
        && chars.all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '$')
        && !is_arkts_reserved_word(name);
    if !valid {
        bail!(
            "N-API export `{name}` is not a legal non-reserved ArkTS binding identifier; rename the UniFFI item"
        );
    }
    Ok(())
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct TypeDefLine {
    kind: String,
    name: String,
    original_name: Option<String>,
    def: String,
    js_doc: Option<String>,
    js_mod: Option<String>,
    extends: Option<String>,
}

fn validate_type_def_declared_name(def: &TypeDefLine) -> Result<()> {
    if def.kind == "fn" {
        let declaration = def.def.trim();
        let declared = declaration
            .strip_prefix("function ")
            .and_then(|rest| rest.split_once('(').map(|(name, _)| name.trim()))
            .filter(|name| !name.is_empty())
            .with_context(|| {
                format!(
                    "raw OHOS callable `{}` has a malformed declaration `{}`",
                    def.name, def.def
                )
            })?;
        if declared != def.name {
            bail!(
                "raw OHOS callable metadata name `{}` does not match declaration `{declared}`",
                def.name
            );
        }
    }
    Ok(())
}

fn validate_raw_type_def_uniqueness(defs: &[TypeDefLine]) -> Result<()> {
    let mut names = BTreeMap::<String, (&str, &str)>::new();
    for def in defs {
        validate_type_def_declared_name(def)?;
        if def.name.is_empty()
            || def.kind == "fn"
            || matches!(def.kind.as_str(), "impl" | "extends")
        {
            continue;
        }
        for name in std::iter::once(def.name.as_str()).chain(
            def.original_name
                .as_deref()
                .filter(|original| *original != def.name),
        ) {
            if let Some((kind, body)) = names.insert(name.to_string(), (&def.kind, &def.def)) {
                if kind != def.kind || body != def.def {
                    bail!(
                        "duplicate raw OHOS type `{name}` has incompatible declarations: `{kind}` `{body}` versus `{}` `{}`",
                        def.kind,
                        def.def
                    );
                }
                bail!(
                    "duplicate raw OHOS type declaration for `{name}` repeats `{}` `{}`",
                    def.kind,
                    def.def
                );
            }
        }
    }
    Ok(())
}

fn collect_type_defs(
    type_dir: &Utf8Path,
    files: &[FacadeInventoryFile],
    defs: &mut Vec<TypeDefLine>,
) -> Result<()> {
    let mut files = files.iter().collect::<Vec<_>>();
    files.sort_by(|left, right| left.file.cmp(&right.file));
    for entry in files {
        let path = type_dir.join(&entry.file);
        let bytes = read_verified_regular_file(&path)?;
        if sha256_bytes(&bytes) != entry.sha256 {
            bail!("OHOS type definition changed before consumption: {path}");
        }
        for line in BufReader::new(Cursor::new(bytes)).lines() {
            let line = line?;
            if let Some(def) = parse_type_def_line(&line)? {
                defs.push(def);
            } else if !line.trim().is_empty() {
                defs.push(TypeDefLine {
                    kind: "raw".to_string(),
                    name: String::new(),
                    original_name: None,
                    def: line.to_string(),
                    js_doc: None,
                    js_mod: None,
                    extends: None,
                });
            }
        }
    }
    let mut normalized: Vec<TypeDefLine> = Vec::with_capacity(defs.len());
    for def in defs.drain(..) {
        if def.kind == "struct" {
            if let Some(existing) = normalized.iter_mut().find(|existing| {
                existing.kind == def.kind && existing.name == def.name && existing.def == def.def
            }) {
                if existing.js_mod.is_some()
                    && def.js_mod.is_some()
                    && existing.js_mod != def.js_mod
                {
                    bail!(
                        "duplicate raw OHOS class `{}` appears in incompatible modules",
                        def.name
                    );
                }
                if existing.original_name.is_some()
                    && def.original_name.is_some()
                    && existing.original_name != def.original_name
                {
                    bail!(
                        "duplicate raw OHOS class `{}` has incompatible original names",
                        def.name
                    );
                }
                if existing.js_mod.is_none() {
                    existing.js_mod = def.js_mod;
                }
                if existing.original_name.is_none() {
                    existing.original_name = def.original_name;
                }
                if existing.js_doc.as_deref().unwrap_or_default().is_empty()
                    && def.js_doc.as_deref().is_some_and(|doc| !doc.is_empty())
                {
                    existing.js_doc = def.js_doc;
                }
                continue;
            }
        } else if matches!(def.kind.as_str(), "impl" | "extends")
            && normalized.iter().any(|existing| existing == &def)
        {
            continue;
        }
        normalized.push(def);
    }
    *defs = normalized;
    Ok(())
}

fn parse_type_def_line(line: &str) -> Result<Option<TypeDefLine>> {
    let mut trimmed = line.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    if !trimmed.starts_with('{') {
        let Some((_, suffix)) = trimmed.split_once(':') else {
            return Ok(None);
        };
        trimmed = suffix.trim();
    }
    if !trimmed.starts_with('{') {
        return Ok(None);
    }
    let value: Value = serde_json::from_str(trimmed)
        .with_context(|| format!("parsing OHOS type definition JSON line: {trimmed}"))?;
    Ok(Some(TypeDefLine {
        kind: value
            .get("kind")
            .and_then(Value::as_str)
            .unwrap_or("raw")
            .to_string(),
        name: value
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        original_name: value
            .get("original_name")
            .and_then(Value::as_str)
            .map(str::to_string),
        def: value
            .get("def")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .replace("\\n", "\n"),
        js_doc: value
            .get("js_doc")
            .and_then(Value::as_str)
            .map(|doc| doc.replace("\\n", "\n")),
        js_mod: value
            .get("js_mod")
            .and_then(Value::as_str)
            .map(str::to_string),
        extends: value
            .get("extends")
            .and_then(Value::as_str)
            .map(str::to_string),
    }))
}

fn render_index_d_ts(defs: Vec<TypeDefLine>) -> String {
    if defs.is_empty() {
        return TYPE_HEADER.to_string();
    }
    let mut grouped: BTreeMap<String, Vec<TypeDefLine>> = BTreeMap::new();
    let mut class_defs: BTreeMap<(String, String), TypeDefLine> = BTreeMap::new();
    for def in defs {
        let namespace = def
            .js_mod
            .clone()
            .unwrap_or_else(|| "__TOP_LEVEL_MODULE__".to_string());
        match def.kind.as_str() {
            "struct" => {
                class_defs.insert((namespace, def.name.clone()), def);
            }
            "extends" => {
                if let Some(class_def) = class_defs.get_mut(&(namespace, def.name.clone())) {
                    class_def.extends = Some(def.def);
                }
            }
            "impl" => {
                if let Some(class_def) = class_defs.get_mut(&(namespace, def.name.clone())) {
                    if !class_def.def.is_empty() {
                        class_def.def.push('\n');
                    }
                    class_def.def.push_str(&def.def);
                }
            }
            _ => grouped.entry(namespace).or_default().push(def),
        }
    }
    for ((namespace, _), def) in class_defs {
        grouped.entry(namespace).or_default().push(def);
    }

    let mut out = TYPE_HEADER.to_string();
    for (namespace, mut defs) in grouped {
        defs.sort_by(|a, b| a.name.cmp(&b.name));
        if namespace == "__TOP_LEVEL_MODULE__" {
            for def in defs {
                out.push_str(&pretty_type_def(&def, false));
                out.push('\n');
            }
        } else {
            out.push_str(&format!("export namespace {namespace} {{\n"));
            for def in defs {
                out.push_str(&indent(&pretty_type_def(&def, true), 2));
                out.push('\n');
            }
            out.push_str("}\n");
        }
    }
    out.replace("Buffer", "ArrayBuffer")
        .replace("ExternalObject<", "ExternalObject<")
}

fn pretty_type_def(def: &TypeDefLine, ambient: bool) -> String {
    let mut out = def.js_doc.clone().unwrap_or_default();
    let declare = if ambient { "export" } else { "export declare" };
    match def.kind.as_str() {
        "interface" => out.push_str(&format!(
            "export interface {} {{\n{}\n}}",
            def.name, def.def
        )),
        "enum" => out.push_str(&format!(
            "{declare} const enum {} {{\n{}\n}}",
            def.name, def.def
        )),
        "string_enum" => {
            let values = def
                .def
                .split(',')
                .filter_map(|entry| entry.split_once('=').map(|(_, rhs)| rhs.trim()))
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>();
            let values = if values.is_empty() {
                def.def.clone()
            } else {
                values.join(" | ")
            };
            out.push_str(&format!("export type {} = {};", def.name, values));
        }
        "type" => {
            if let Some(rendered) = render_arkts_payload_union(&def.name, &def.def) {
                out.push_str(&rendered);
            } else {
                out.push_str(&format!("export type {} = \n{}", def.name, def.def));
            }
        }
        "struct" => {
            let extends = def
                .extends
                .as_ref()
                .map(|extends| format!(" extends {extends}"))
                .unwrap_or_default();
            out.push_str(&format!(
                "{declare} class {}{} {{\n{}\n}}",
                def.name, extends, def.def
            ));
            if let Some(original_name) = &def.original_name {
                if original_name != &def.name {
                    out.push_str(&format!("\nexport type {original_name} = {}", def.name));
                }
            }
        }
        "fn" => out.push_str(&format!("{declare} {}", def.def)),
        "raw" => out.push_str(&def.def),
        _ => out.push_str(&def.def),
    }
    if def.kind != "struct" {
        if let Some(original_name) = &def.original_name {
            if original_name != &def.name {
                out.push_str(&format!("\nexport type {original_name} = {};", def.name));
            }
        }
    }
    out
}

fn render_arkts_payload_union(name: &str, definition: &str) -> Option<String> {
    let mut bodies = Vec::new();
    let mut start = None;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    for (index, ch) in definition.char_indices() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        if ch == '\'' || ch == '"' {
            quote = Some(ch);
            continue;
        }
        match ch {
            '{' => {
                if depth == 0 {
                    start = Some(index + ch.len_utf8());
                }
                depth += 1;
            }
            '}' if depth > 0 => {
                depth -= 1;
                if depth == 0 {
                    bodies.push(definition[start?..index].trim().to_string());
                    start = None;
                }
            }
            _ => {}
        }
    }
    if depth != 0 || bodies.is_empty() {
        return None;
    }

    let mut interfaces = Vec::new();
    for body in bodies {
        let fields = split_top_level_fields(&body)?;
        let tag = fields.iter().find_map(|field| {
            let (key, value) = field.split_once(':')?;
            if key.trim() != "type" {
                return None;
            }
            let value = value.trim();
            (value.len() >= 2
                && ((value.starts_with('\'') && value.ends_with('\''))
                    || (value.starts_with('"') && value.ends_with('"'))))
            .then(|| value[1..value.len() - 1].to_string())
        })?;
        let suffix = arkts_type_suffix(&tag)?;
        let interface_name = format!("{name}{suffix}");
        validate_arkts_export_identifier(&interface_name).ok()?;
        interfaces.push((interface_name, fields));
    }

    let mut out = String::new();
    for (interface_name, fields) in &interfaces {
        out.push_str(&format!("export interface {interface_name} {{\n"));
        for field in fields {
            out.push_str("  ");
            out.push_str(field.trim());
            if !field.trim_end().ends_with(';') {
                out.push(';');
            }
            out.push('\n');
        }
        out.push_str("}\n");
    }
    out.push_str(&format!(
        "export type {name} = {};",
        interfaces
            .iter()
            .map(|(interface_name, _)| interface_name.as_str())
            .collect::<Vec<_>>()
            .join(" | ")
    ));
    Some(out)
}

fn split_top_level_fields(body: &str) -> Option<Vec<String>> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    for (index, ch) in body.char_indices() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        if ch == '\'' || ch == '"' {
            quote = Some(ch);
            continue;
        }
        match ch {
            '<' | '(' | '[' | '{' => depth += 1,
            '>' | ')' | ']' | '}' if depth > 0 => depth -= 1,
            ',' if depth == 0 => {
                let field = body[start..index].trim();
                if !field.is_empty() {
                    out.push(field.to_string());
                }
                start = index + ch.len_utf8();
            }
            _ => {}
        }
    }
    if quote.is_some() || depth != 0 {
        return None;
    }
    let field = body[start..].trim();
    if !field.is_empty() {
        out.push(field.to_string());
    }
    (!out.is_empty()).then_some(out)
}

fn arkts_type_suffix(tag: &str) -> Option<String> {
    let mut out = String::new();
    let mut uppercase_next = true;
    for ch in tag.chars() {
        if ch.is_ascii_alphanumeric() {
            if uppercase_next {
                out.push(ch.to_ascii_uppercase());
            } else {
                out.push(ch);
            }
            uppercase_next = false;
        } else {
            uppercase_next = true;
        }
    }
    (!out.is_empty()).then_some(out)
}

fn indent(src: &str, spaces: usize) -> String {
    let prefix = " ".repeat(spaces);
    src.lines()
        .map(|line| {
            if line.is_empty() {
                String::new()
            } else {
                format!("{prefix}{line}")
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

